window.CHUJI_DATA_9 = [{"l": 381, "lt": "Lesson 81 A Heavy Price to Pay 惨重的代价", "i": 1, "type": "reading", "en": "Tom's father died of lung cancer.", "zh": "汤姆的父亲死于肺癌。", "audio": "chuji_l81_01.mp3", "localAudio": "audio_chunks/chuji_l81_01.mp3", "b64": "", "src": "chuji"}, {"l": 381, "lt": "Lesson 81 A Heavy Price to Pay 惨重的代价", "i": 2, "type": "reading", "en": "He couldn't stop smoking.", "zh": "他无法戒烟。", "audio": "chuji_l81_02.mp3", "localAudio": "audio_chunks/chuji_l81_02.mp3", "b64": "", "src": "chuji"}, {"l": 381, "lt": "Lesson 81 A Heavy Price to Pay 惨重的代价", "i": 3, "type": "reading", "en": "He tried quitting several times.", "zh": "他尝试戒了几次。", "audio": "chuji_l81_03.mp3", "localAudio": "audio_chunks/chuji_l81_03.mp3", "b64": "", "src": "chuji"}, {"l": 381, "lt": "Lesson 81 A Heavy Price to Pay 惨重的代价", "i": 4, "type": "reading", "en": "However, whenever he saw someone smoking, he couldn't resist lighting up.", "zh": "不过，每当他看到有人抽烟时，他就无法抗拒要点根烟。", "audio": "chuji_l81_04.mp3", "localAudio": "audio_chunks/chuji_l81_04.mp3", "b64": "", "src": "chuji"}, {"l": 381, "lt": "Lesson 81 A Heavy Price to Pay 惨重的代价", "i": 5, "type": "reading", "en": "In the end, he gave up trying.", "zh": "最后，他放弃了尝试。", "audio": "chuji_l81_05.mp3", "localAudio": "audio_chunks/chuji_l81_05.mp3", "b64": "", "src": "chuji"}, {"l": 381, "lt": "Lesson 81 A Heavy Price to Pay 惨重的代价", "i": 6, "type": "reading", "en": "It was no use stopping one day and starting again the next.", "zh": "因为一天停下来，第二天又开始是没有用的。", "audio": "chuji_l81_06.mp3", "localAudio": "audio_chunks/chuji_l81_06.mp3", "b64": "", "src": "chuji"}, {"l": 381, "lt": "Lesson 81 A Heavy Price to Pay 惨重的代价", "i": 7, "type": "reading", "en": "He enjoyed smoking too much.", "zh": "他太喜欢抽烟了。", "audio": "chuji_l81_07.mp3", "localAudio": "audio_chunks/chuji_l81_07.mp3", "b64": "", "src": "chuji"}, {"l": 381, "lt": "Lesson 81 A Heavy Price to Pay 惨重的代价", "i": 8, "type": "reading", "en": "He certainly paid a heavy price, though.", "zh": "不过，他也的确付出了惨重的代价。", "audio": "chuji_l81_08.mp3", "localAudio": "audio_chunks/chuji_l81_08.mp3", "b64": "", "src": "chuji"}, {"l": 382, "lt": "Lesson 82 Smoking Isn't Allowed 不准吸烟", "i": 1, "type": "dialog", "en": "Would you mind putting out your cigarette?", "zh": "请你把烟熄掉好吗？", "audio": "chuji_l82_01.mp3", "localAudio": "audio_chunks/chuji_l82_01.mp3", "b64": "", "src": "chuji", "speaker": "Usher", "note": "说话人: Usher"}, {"l": 382, "lt": "Lesson 82 Smoking Isn't Allowed 不准吸烟", "i": 2, "type": "dialog", "en": "I'll just finish smoking this one, OK?", "zh": "我只要把这一根抽完，好吗？", "audio": "chuji_l82_02.mp3", "localAudio": "audio_chunks/chuji_l82_02.mp3", "b64": "", "src": "chuji", "speaker": "Betty", "note": "说话人: Betty"}, {"l": 382, "lt": "Lesson 82 Smoking Isn't Allowed 不准吸烟", "i": 3, "type": "dialog", "en": "Smoking isn't allowed in movie theaters.", "zh": "戏院里是不准吸烟的。", "audio": "chuji_l82_03.mp3", "localAudio": "audio_chunks/chuji_l82_03.mp3", "b64": "", "src": "chuji", "speaker": "Usher", "note": "说话人: Usher"}, {"l": 382, "lt": "Lesson 82 Smoking Isn't Allowed 不准吸烟", "i": 4, "type": "dialog", "en": "Oh, I'm sorry.", "zh": "哦，很抱歉。", "audio": "chuji_l82_04.mp3", "localAudio": "audio_chunks/chuji_l82_04.mp3", "b64": "", "src": "chuji", "speaker": "Betty", "note": "说话人: Betty"}, {"l": 383, "lt": "Lesson 83 A Nice Person 大好人", "i": 1, "type": "reading", "en": "Shelly doesn't like people who are unreliable.", "zh": "谢莉不喜欢不可靠的人。", "audio": "chuji_l83_01.mp3", "localAudio": "audio_chunks/chuji_l83_01.mp3", "b64": "", "src": "chuji"}, {"l": 383, "lt": "Lesson 83 A Nice Person 大好人", "i": 2, "type": "reading", "en": "She especially doesn't like people who tell lies.", "zh": "她特别不喜欢说谎的人。", "audio": "chuji_l83_02.mp3", "localAudio": "audio_chunks/chuji_l83_02.mp3", "b64": "", "src": "chuji"}, {"l": 383, "lt": "Lesson 83 A Nice Person 大好人", "i": 3, "type": "reading", "en": "On the other hand, she likes people who are humorous and honest.", "zh": "另一方面，她喜欢那些幽默又诚实的人。", "audio": "chuji_l83_03.mp3", "localAudio": "audio_chunks/chuji_l83_03.mp3", "b64": "", "src": "chuji"}, {"l": 383, "lt": "Lesson 83 A Nice Person 大好人", "i": 4, "type": "reading", "en": "She really likes people that are easygoing and sincere.", "zh": "她实在喜欢随和又诚恳的人。", "audio": "chuji_l83_04.mp3", "localAudio": "audio_chunks/chuji_l83_04.mp3", "b64": "", "src": "chuji"}, {"l": 383, "lt": "Lesson 83 A Nice Person 大好人", "i": 5, "type": "reading", "en": "However, regardless of whom she likes or dislikes, she is nice to everyone.", "zh": "然而，不论她喜欢谁或不喜欢谁，她对每个人都很好。", "audio": "chuji_l83_05.mp3", "localAudio": "audio_chunks/chuji_l83_05.mp3", "b64": "", "src": "chuji"}, {"l": 384, "lt": "Lesson 84 What's She Like? 她是什么样的人呢？", "i": 1, "type": "dialog", "en": "Hi, Larry! Would you like to meet my roommate, Sally?", "zh": "嗨，拉里！你要不要见一见我的室友萨莉？", "audio": "chuji_l84_01.mp3", "localAudio": "audio_chunks/chuji_l84_01.mp3", "b64": "", "src": "chuji", "speaker": "Anna", "note": "说话人: Anna"}, {"l": 384, "lt": "Lesson 84 What's She Like? 她是什么样的人呢？", "i": 2, "type": "dialog", "en": "Sure. What's she like?", "zh": "好啊。她是什么样的人呢？", "audio": "chuji_l84_02.mp3", "localAudio": "audio_chunks/chuji_l84_02.mp3", "b64": "", "src": "chuji", "speaker": "Larry", "note": "说话人: Larry"}, {"l": 384, "lt": "Lesson 84 What's She Like? 她是什么样的人呢？", "i": 3, "type": "dialog", "en": "She's just your type.", "zh": "她是属于你这一型的。", "audio": "chuji_l84_03.mp3", "localAudio": "audio_chunks/chuji_l84_03.mp3", "b64": "", "src": "chuji", "speaker": "Anna", "note": "说话人: Anna"}, {"l": 384, "lt": "Lesson 84 What's She Like? 她是什么样的人呢？", "i": 4, "type": "dialog", "en": "What do you mean?", "zh": "你是什么意思啊？", "audio": "chuji_l84_04.mp3", "localAudio": "audio_chunks/chuji_l84_04.mp3", "b64": "", "src": "chuji", "speaker": "Larry", "note": "说话人: Larry"}, {"l": 384, "lt": "Lesson 84 What's She Like? 她是什么样的人呢？", "i": 5, "type": "dialog", "en": "She's just like you, a bookworm.", "zh": "她就像你一样，是个书呆子。", "audio": "chuji_l84_05.mp3", "localAudio": "audio_chunks/chuji_l84_05.mp3", "b64": "", "src": "chuji", "speaker": "Anna", "note": "说话人: Anna"}, {"l": 385, "lt": "Lesson 85 Blood Types 血型", "i": 1, "type": "reading", "en": "Some people believe that one's personality is related to one's blood type.", "zh": "有些人相信一个人的个性与他的血型有关。", "audio": "chuji_l85_01.mp3", "localAudio": "audio_chunks/chuji_l85_01.mp3", "b64": "", "src": "chuji"}, {"l": 385, "lt": "Lesson 85 Blood Types 血型", "i": 2, "type": "reading", "en": "There are three main blood types: A, B and O.", "zh": "一共有三种主要的血型：A型、B型及O型。", "audio": "chuji_l85_02.mp3", "localAudio": "audio_chunks/chuji_l85_02.mp3", "b64": "", "src": "chuji"}, {"l": 385, "lt": "Lesson 85 Blood Types 血型", "i": 3, "type": "reading", "en": "Type A people are introverts whereas type O people are extroverts.", "zh": "A型人内向而O型人则外向。", "audio": "chuji_l85_03.mp3", "localAudio": "audio_chunks/chuji_l85_03.mp3", "b64": "", "src": "chuji"}, {"l": 385, "lt": "Lesson 85 Blood Types 血型", "i": 4, "type": "reading", "en": "Type B people are a mixture of both A and O.", "zh": "B型人是A型和O型的混合。", "audio": "chuji_l85_04.mp3", "localAudio": "audio_chunks/chuji_l85_04.mp3", "b64": "", "src": "chuji"}, {"l": 385, "lt": "Lesson 85 Blood Types 血型", "i": 5, "type": "reading", "en": "They are more relaxed and don't get bothered easily.", "zh": "他们比较轻松自在而且不容易觉得烦。", "audio": "chuji_l85_05.mp3", "localAudio": "audio_chunks/chuji_l85_05.mp3", "b64": "", "src": "chuji"}, {"l": 385, "lt": "Lesson 85 Blood Types 血型", "i": 6, "type": "reading", "en": "When it comes to choosing a spouse, remember some of these facts.", "zh": "谈到择偶的时候，切记以上这些事实。", "audio": "chuji_l85_06.mp3", "localAudio": "audio_chunks/chuji_l85_06.mp3", "b64": "", "src": "chuji"}, {"l": 386, "lt": "Lesson 86 What's Your Blood Type? 你是什么血型？", "i": 1, "type": "dialog", "en": "What's your blood type, Luke?", "zh": "卢克，你是什么血型？", "audio": "chuji_l86_01.mp3", "localAudio": "audio_chunks/chuji_l86_01.mp3", "b64": "", "src": "chuji", "speaker": "Bella", "note": "说话人: Bella"}, {"l": 386, "lt": "Lesson 86 What's Your Blood Type? 你是什么血型？", "i": 2, "type": "dialog", "en": "It's A, I think. Why do you ask?", "zh": "我想是A型。你问这干嘛？", "audio": "chuji_l86_02.mp3", "localAudio": "audio_chunks/chuji_l86_02.mp3", "b64": "", "src": "chuji", "speaker": "Luke", "note": "说话人: Luke"}, {"l": 386, "lt": "Lesson 86 What's Your Blood Type? 你是什么血型？", "i": 3, "type": "dialog", "en": "Well, mine's B.", "zh": "嗯，我的血型是B。", "audio": "chuji_l86_03.mp3", "localAudio": "audio_chunks/chuji_l86_03.mp3", "b64": "", "src": "chuji", "speaker": "Bella", "note": "说话人: Bella"}, {"l": 386, "lt": "Lesson 86 What's Your Blood Type? 你是什么血型？", "i": 4, "type": "dialog", "en": "So?", "zh": "那又怎么样呢？", "audio": "chuji_l86_04.mp3", "localAudio": "audio_chunks/chuji_l86_04.mp3", "b64": "", "src": "chuji", "speaker": "Luke", "note": "说话人: Luke"}, {"l": 386, "lt": "Lesson 86 What's Your Blood Type? 你是什么血型？", "i": 5, "type": "dialog", "en": "They say people with A blood type get along very well with those with B blood type.", "zh": "据说A型的人与B型的人相处得很好。", "audio": "chuji_l86_05.mp3", "localAudio": "audio_chunks/chuji_l86_05.mp3", "b64": "", "src": "chuji", "speaker": "Bella", "note": "说话人: Bella"}, {"l": 386, "lt": "Lesson 86 What's Your Blood Type? 你是什么血型？", "i": 6, "type": "dialog", "en": "Really?", "zh": "真的吗？", "audio": "chuji_l86_06.mp3", "localAudio": "audio_chunks/chuji_l86_06.mp3", "b64": "", "src": "chuji", "speaker": "Luke", "note": "说话人: Luke"}, {"l": 387, "lt": "Lesson 87 Society Is Changing Rapidly 社会正快速地变化", "i": 1, "type": "reading", "en": "Society is changing rapidly.", "zh": "社会正快速地变化。", "audio": "chuji_l87_01.mp3", "localAudio": "audio_chunks/chuji_l87_01.mp3", "b64": "", "src": "chuji"}, {"l": 387, "lt": "Lesson 87 Society Is Changing Rapidly 社会正快速地变化", "i": 2, "type": "reading", "en": "As a result, more and more people are suffering from stress.", "zh": "因此，越来越多的人正遭受压力之苦。", "audio": "chuji_l87_02.mp3", "localAudio": "audio_chunks/chuji_l87_02.mp3", "b64": "", "src": "chuji"}, {"l": 387, "lt": "Lesson 87 Society Is Changing Rapidly 社会正快速地变化", "i": 3, "type": "reading", "en": "Those who are stressed out are often nervous, angry or ill.", "zh": "凡是压力过大的人经常会紧张、生气或生病。", "audio": "chuji_l87_03.mp3", "localAudio": "audio_chunks/chuji_l87_03.mp3", "b64": "", "src": "chuji"}, {"l": 387, "lt": "Lesson 87 Society Is Changing Rapidly 社会正快速地变化", "i": 4, "type": "reading", "en": "People must, therefore, learn to deal with this \"new\" kind of problem.", "zh": "因此，人们必须学会处理这种“新”问题。", "audio": "chuji_l87_04.mp3", "localAudio": "audio_chunks/chuji_l87_04.mp3", "b64": "", "src": "chuji"}, {"l": 387, "lt": "Lesson 87 Society Is Changing Rapidly 社会正快速地变化", "i": 5, "type": "reading", "en": "Regular exercise is one way.", "zh": "规律的运动是一种方法。", "audio": "chuji_l87_05.mp3", "localAudio": "audio_chunks/chuji_l87_05.mp3", "b64": "", "src": "chuji"}, {"l": 387, "lt": "Lesson 87 Society Is Changing Rapidly 社会正快速地变化", "i": 6, "type": "reading", "en": "The best way, however, is to keep a good sense of humor.", "zh": "不过，最好的方法就是保持良好的幽默感。", "audio": "chuji_l87_06.mp3", "localAudio": "audio_chunks/chuji_l87_06.mp3", "b64": "", "src": "chuji"}, {"l": 388, "lt": "Lesson 88 You Need a Vacation 你需要度个假", "i": 1, "type": "dialog", "en": "What's the matter, Luke? You look stressed out.", "zh": "卢克，你怎么了？你看来像是受到很大的压力。", "audio": "chuji_l88_01.mp3", "localAudio": "audio_chunks/chuji_l88_01.mp3", "b64": "", "src": "chuji", "speaker": "Shirley", "note": "说话人: Shirley"}, {"l": 388, "lt": "Lesson 88 You Need a Vacation 你需要度个假", "i": 2, "type": "dialog", "en": "I'm under a lot of pressure at work.", "zh": "我在工作上受到很大的压力。", "audio": "chuji_l88_02.mp3", "localAudio": "audio_chunks/chuji_l88_02.mp3", "b64": "", "src": "chuji", "speaker": "Luke", "note": "说话人: Luke"}, {"l": 388, "lt": "Lesson 88 You Need a Vacation 你需要度个假", "i": 3, "type": "dialog", "en": "You need a long vacation.", "zh": "你需要度个长假。", "audio": "chuji_l88_03.mp3", "localAudio": "audio_chunks/chuji_l88_03.mp3", "b64": "", "src": "chuji", "speaker": "Shirley", "note": "说话人: Shirley"}, {"l": 388, "lt": "Lesson 88 You Need a Vacation 你需要度个假", "i": 4, "type": "dialog", "en": "I know, but I really don't have the time.", "zh": "我知道，但我真地没有时间。", "audio": "chuji_l88_04.mp3", "localAudio": "audio_chunks/chuji_l88_04.mp3", "b64": "", "src": "chuji", "speaker": "Luke", "note": "说话人: Luke"}, {"l": 389, "lt": "Lesson 89 Australia 澳大利亚", "i": 1, "type": "reading", "en": "Australia is a unique country.", "zh": "澳大利亚是一个非常独特的国家。", "audio": "chuji_l89_01.mp3", "localAudio": "audio_chunks/chuji_l89_01.mp3", "b64": "", "src": "chuji"}, {"l": 389, "lt": "Lesson 89 Australia 澳大利亚", "i": 2, "type": "reading", "en": "It's the world's largest island, but it's also the world's smallest continent.", "zh": "它是世界上最大的岛，但它也是世界上最小的洲。", "audio": "chuji_l89_02.mp3", "localAudio": "audio_chunks/chuji_l89_02.mp3", "b64": "", "src": "chuji"}, {"l": 389, "lt": "Lesson 89 Australia 澳大利亚", "i": 3, "type": "reading", "en": "In fact, Australia is the only country that is also a continent.", "zh": "事实上，澳大利亚是唯一也是个洲的国家。", "audio": "chuji_l89_03.mp3", "localAudio": "audio_chunks/chuji_l89_03.mp3", "b64": "", "src": "chuji"}, {"l": 389, "lt": "Lesson 89 Australia 澳大利亚", "i": 4, "type": "reading", "en": "It's about the size of the United States, but it has a population of only 16.5 million.", "zh": "它大约与美国一样大，但它的人口却只有1650万。", "audio": "chuji_l89_04.mp3", "localAudio": "audio_chunks/chuji_l89_04.mp3", "b64": "", "src": "chuji"}, {"l": 389, "lt": "Lesson 89 Australia 澳大利亚", "i": 5, "type": "reading", "en": "If it sounds like an interesting place to visit, that's because it is.", "zh": "如果它听起来像是个值得走访的好去处的话，那是因为它的确是个值得走访的好去处。", "audio": "chuji_l89_05.mp3", "localAudio": "audio_chunks/chuji_l89_05.mp3", "b64": "", "src": "chuji"}, {"l": 390, "lt": "Lesson 90 A Good Place to Visit 一个好玩的地方", "i": 1, "type": "dialog", "en": "Where's a good place to visit, Richie?", "zh": "瑞琪，哪儿有好玩的地方啊？", "audio": "chuji_l90_01.mp3", "localAudio": "audio_chunks/chuji_l90_01.mp3", "b64": "", "src": "chuji", "speaker": "Donna", "note": "说话人: Donna"}, {"l": 390, "lt": "Lesson 90 A Good Place to Visit 一个好玩的地方", "i": 2, "type": "dialog", "en": "Phuket.", "zh": "普吉岛。", "audio": "chuji_l90_02.mp3", "localAudio": "audio_chunks/chuji_l90_02.mp3", "b64": "", "src": "chuji", "speaker": "Richie", "note": "说话人: Richie"}, {"l": 390, "lt": "Lesson 90 A Good Place to Visit 一个好玩的地方", "i": 3, "type": "dialog", "en": "Phu...what?", "zh": "普什么？", "audio": "chuji_l90_03.mp3", "localAudio": "audio_chunks/chuji_l90_03.mp3", "b64": "", "src": "chuji", "speaker": "Donna", "note": "说话人: Donna"}, {"l": 390, "lt": "Lesson 90 A Good Place to Visit 一个好玩的地方", "i": 4, "type": "dialog", "en": "Phuket, in Thailand. It's a beautiful resort island with fantastic beaches.", "zh": "泰国的普吉岛。那是个拥有很棒海滩的美丽度假岛屿。", "audio": "chuji_l90_04.mp3", "localAudio": "audio_chunks/chuji_l90_04.mp3", "b64": "", "src": "chuji", "speaker": "Richie", "note": "说话人: Richie"}, {"l": 390, "lt": "Lesson 90 A Good Place to Visit 一个好玩的地方", "i": 5, "type": "dialog", "en": "Wow! Sounds great!", "zh": "哇！听起来真棒！", "audio": "chuji_l90_05.mp3", "localAudio": "audio_chunks/chuji_l90_05.mp3", "b64": "", "src": "chuji", "speaker": "Donna", "note": "说话人: Donna"}];